mockups.css:
:root{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent:#a9c24f;--accent-soft:#eaf2ce;--accent-fg:#56701f;--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--danger:#b23b3b;--danger-soft:#f6e4e2;--mint:#1b8168;--teal:#6fb6b8}
*{box-sizing:border-box}
body{margin:0;font-family:Figtree,"Segoe UI",system-ui,sans-serif;color:var(--ink);background:var(--stage)}
.row{display:flex;flex-wrap:wrap;gap:28px;padding:24px;align-items:flex-start}
.state{display:flex;flex-direction:column;gap:8px}
.state>.cap{font-size:12px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--ink-soft)}
.phone{width:360px;min-height:640px;background:var(--cream);border:1px solid var(--line);border-radius:32px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 30px 60px -30px rgba(30,46,39,.28)}
.topbar{height:52px;background:var(--paper);border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 16px;gap:10px;font-weight:800}
.logo{font-family:"Bricolage Grotesque",system-ui;font-weight:800;color:#ff6a0d;font-size:20px}
.content{flex:1;padding:16px 16px 20px}
.bottomnav{height:60px;background:var(--paper);border-top:1px solid var(--line);display:flex;justify-content:space-around;align-items:center;font-size:11px;color:var(--ink-soft);font-weight:700}
.bottomnav .on{color:var(--primary-fg)}
h1{font-family:"Bricolage Grotesque",system-ui;font-weight:800;font-size:26px;letter-spacing:-.01em;margin:4px 0 4px;line-height:1.15}
.sub{color:var(--ink-soft);font-size:15px;margin:0 0 14px}
.back{font-size:14px;font-weight:800;color:var(--primary-fg);margin-bottom:6px;display:inline-block}
.sec{font-size:12px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-soft);margin:18px 4px 8px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:4px 16px}
.list{background:var(--paper);border:1px solid var(--line);border-radius:24px;overflow:hidden}
.list .li{display:flex;align-items:center;gap:12px;min-height:52px;padding:14px 16px;border-top:1px solid var(--line);font-weight:600}
.list .li:first-child{border-top:0}
.list .li .meta{margin-left:auto;color:var(--ink-soft);font-size:14px;font-weight:500}
.chev{color:var(--ink-soft)}
.new{outline:2px dashed var(--accent);outline-offset:-4px}
.trow{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-top:1px solid var(--line)}
.trow:first-child{border-top:0}
.trow strong{display:block;font-size:14px}
.trow small{display:block;font-size:12px;color:var(--ink-soft);margin-top:2px}
.sw{position:relative;width:44px;height:26px;border-radius:999px;background:var(--line);flex:none}
.sw.on{background:var(--mint)}
.sw::after{content:"";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.2)}
.sw.on::after{transform:translateX(18px)}
.sw.dis{opacity:.5}
.lock{font-size:12px;font-weight:800;color:var(--ink-soft);background:var(--stage);border-radius:999px;padding:4px 10px;flex:none}
.addr{display:flex;align-items:center;gap:10px;padding:14px 0}
.addr .mail{font-weight:700;font-size:15px;word-break:break-all}
.badge{font-size:12px;font-weight:800;border-radius:999px;padding:3px 10px;flex:none}
.badge.ok{background:var(--primary-soft);color:var(--primary-fg)}
.badge.warn{background:var(--accent-soft);color:var(--accent-fg)}
.badge.bad{background:var(--danger-soft);color:var(--danger)}
.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:999px;background:var(--primary);color:var(--on-primary);font-weight:800;font-size:13px;padding:10px 14px;font-family:inherit}
.btn.lg{width:100%;min-height:54px;font-size:17px}
.btn.ghost{background:transparent;border:1.5px solid var(--line);color:var(--ink-soft)}
.btn.danger{background:var(--danger)}
.status{border-radius:16px;background:var(--primary-soft);color:var(--primary-fg);padding:10px 14px;font-size:13px;font-weight:700;margin:10px 0}
.alert{border-radius:16px;background:var(--danger-soft);color:var(--danger);padding:10px 14px;font-size:14px;margin:10px 0}
.info{border-radius:16px;background:var(--stage);color:var(--ink);padding:10px 14px;font-size:13px;margin:10px 0}
.hint{display:flex;gap:14px;border-radius:24px;background:var(--accent-soft);padding:18px;margin-bottom:14px}
.hint .ic{width:44px;height:44px;border-radius:16px;background:var(--accent);display:flex;align-items:center;justify-content:center;flex:none;font-size:20px}
.hint h3{margin:2px 0 2px;font-size:16px;font-weight:800}
.hint p{margin:0;font-size:14px}
.hint a{display:inline-block;margin-top:8px;font-size:14px;font-weight:800;color:var(--accent-fg)}
.blk{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:16px;margin-bottom:12px}
.blk h4{margin:0 0 6px;font-size:15px}
.blk p{margin:0;font-size:13px;color:var(--ink-soft)}
.auth{width:440px;background:var(--cream);border:1px solid var(--line);border-radius:28px;padding:28px 28px 32px;position:relative;overflow:hidden;box-shadow:0 30px 60px -30px rgba(30,46,39,.28)}
.auth::before{content:"";position:absolute;top:-40px;right:-44px;width:150px;height:150px;border:2px dashed var(--primary-soft);border-radius:50%}
.auth h1{font-size:30px;max-width:80%}
.lbl{display:block;font-size:14px;font-weight:700;margin:12px 0 6px}
.inp{height:52px;width:100%;border:1.5px solid var(--line);border-radius:16px;background:var(--paper);padding:0 16px;font-size:16px;display:flex;align-items:center;color:var(--ink-soft)}
.inp.err{border-color:var(--danger)}
.ferr{font-size:13px;color:var(--danger);margin-top:6px}
.link{font-weight:800;color:var(--primary-fg);font-size:14px}
.right{text-align:right;margin-top:8px}
.center{text-align:center;margin-top:14px;font-size:14px;color:var(--ink-soft)}
.gbtn{height:52px;border:1.5px solid var(--line);border-radius:999px;background:var(--paper);display:flex;align-items:center;justify-content:center;font-weight:800;margin-top:12px}
.or{text-align:center;color:var(--ink-soft);font-size:13px;margin:14px 0 2px}
.big{font-size:44px;margin:6px 0 4px}
.mailwrap{width:600px;background:#f4f8f0;padding:24px;font-family:Arial,Helvetica,sans-serif}
.mail{background:#fff;border:1px solid #e2eadf;border-radius:16px;padding:28px}
.mail .brand{color:#ff6a0d;font-weight:800;font-size:22px;margin-bottom:18px}
.mail h2{font-size:20px;margin:0 0 10px;color:#1e2e27}
.mail p{font-size:15px;line-height:1.5;color:#1e2e27;margin:0 0 14px}
.mail .cta{display:inline-block;background:#1b8168;color:#fff;border-radius:999px;padding:12px 22px;font-weight:700;text-decoration:none}
.mail .foot{font-size:12px;color:#5c7069;margin-top:22px;border-top:1px solid #e2eadf;padding-top:14px;line-height:1.5}
.mail .foot a{color:#117b63}
.hdr{font-family:ui-monospace,Consolas,monospace;font-size:11px;color:#5c7069;background:#fff;border:1px dashed #cbdac7;border-radius:10px;padding:10px;margin-bottom:12px;white-space:pre-wrap}

